export const liftFilmCaptions=Object.freeze([{"start": 0.3, "end": 5.9, "text": "A fallen beam blocks the mill lane. A pole over a log makes a lever."}, {"start": 6.3, "end": 10.35, "text": "Log in the middle: your push is as big as the lift, and both ends move the same distance."}, {"start": 10.35, "end": 16.9, "text": "Roll the log close to the beam: half the push, but your end moves twice as far."}, {"start": 17.3, "end": 24.9, "text": "Half the push, twice the distance. In this model, push times the distance pushed down stays the same."}, {"start": 25.3, "end": 33.9, "text": "A ramp four times as long as it is high: a quarter of the force, four times the distance. (A model: no friction.)"}, {"start": 34.0, "end": 38.0, "text": "Less push, longer path. Real machines have friction, so you need more push than this."}].map(Object.freeze));
const intro="See how a longer movement can need less force. These are simplified drawings, with different examples and numbers from your delivery.", explanation="Your ramp and lever jobs will wait. Pause any time or read the words below. Return to find your delivery as you left it.", about=["These are drawn examples, not a filmed experiment or a real lifting plan. In the lever scenes, the film's “lift” is the upward force at one end of the fallen beam. The beam turns around its other end; that lift force is not the whole weight of the beam. Our yard lifts a hanging load and uses its own numbers.", "These models imagine slow, steady movement and ignore friction and other losses. For the same load and rise, less force needs a longer movement; whole-trip input work stays the same. For the lever's downward push, count the distance moved down, not the curved path of the handle. In the work rectangles, a sideways distance arrow stands for the distance pushed down. The ramp's 4 m guide follows its slope, not the ground.", "The film is an approximate explanatory drawing. Its pole, arrows and paths are not measurements or a construction plan. The yard's rigid pole is a separate model; do not measure the film's pictures to choose its arms or steps. Real friction requires more push than the ideal model."], credit="Corrected derivative of the original After the Storm film made with Claude Motion. Andika lettering rendered in the picture, SIL Open Font License 1.1. No authoring player or font files included.";
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,disabled=false)=>`<button type="button" data-lift-film-action="${action}"${disabled?' disabled':''}>${esc(label)}</button>`;
let liftFilmCleanup=null,liftFilmPause=null;
export function pauseLiftFilm(){liftFilmPause?.();}
export function stopLiftFilm(){liftFilmCleanup?.();liftFilmCleanup=null;liftFilmPause=null;}
export function liftFilmEntry(){return `<button type="button" class="ly-film-invitation" data-lift-action="watch"><span>Watch the lifting film<small>Optional silent film · 38 seconds</small></span></button>`;}
export function liftFilmPage(){return `<section class="ly-movie" data-lift-film-movie><div class="ly-film-heading"><h2>Less push, longer path</h2><button type="button" data-lift-film-return>Return to my delivery</button></div><p>${esc(intro)}</p><p>${esc(explanation)}</p><video controls playsinline muted preload="none" poster="./assets/ramp-lever-corrected.jpg" aria-label="Less push, longer path, silent corrected film" aria-describedby="lift-film-caption"></video><p id="lift-film-caption" class="ly-film-caption" data-lift-film-caption>Read the complete transcript below at any time.</p><div class="ly-film-controls">${button('play','Play',true)}${button('replay','Replay',true)}${button('retry','Retry loading')}</div><p data-lift-film-load-status role="status"></p><details data-lift-film-transcript><summary>Read the complete film transcript</summary><ol>${liftFilmCaptions.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol></details><details><summary>About these drawings</summary>${about.map(p=>`<p>${esc(p)}</p>`).join('')}</details><p class="ly-film-credit">${esc(credit)}</p></section>`;}
export function bindLiftFilm(root,live,beforePlay){
 stopLiftFilm();const video=root.querySelector('video'),play=root.querySelector('[data-lift-film-action=play]'),replay=root.querySelector('[data-lift-film-action=replay]'),retry=root.querySelector('[data-lift-film-action=retry]'),status=root.querySelector('[data-lift-film-load-status]'),caption=root.querySelector('[data-lift-film-caption]');
 let disposed=false,revision=0,playRevision=0,wanted=false,controller=null,source=null,track=null,playTask=null;const off=[];
 const on=(target,event,fn)=>{target.addEventListener(event,fn);off.push(()=>target.removeEventListener(event,fn));};
 const current=()=>!disposed&&live(),active=()=>current()&&!document.hidden;
 const pause=()=>{wanted=false;playRevision++;video.pause();if(current())play.textContent='Play';};liftFilmPause=pause;
 const detach=()=>{video.removeAttribute('src');track?.remove();track=null;video.load();if(source){URL.revokeObjectURL(source);source=null;}};
 const failure=()=>{if(current())status.textContent='The film could not play here. Read the transcript or return to your delivery.';};
 const updateCaption=()=>{if(current())caption.textContent=(video.ended?liftFilmCaptions.at(-1):liftFilmCaptions.find(c=>video.currentTime>=c.start&&video.currentTime<c.end))?.text||'\u00a0';};
 const requestPlay=()=>{if(!active()||!source)return;wanted=true;const serial=++playRevision,task={serial,revision};playTask=task;try{Promise.resolve(video.play()).then(()=>{if(playTask!==task)return;playTask=null;if(!active()||!wanted||serial!==playRevision||task.revision!==revision)video.pause();}).catch(e=>{if(playTask===task)playTask=null;if(e?.name!=='AbortError'&&current()&&serial===playRevision&&task.revision===revision){wanted=false;failure();}});}catch{playTask=null;wanted=false;failure();}};
 const load=async auto=>{
  if(!current())return;pause();controller?.abort();const rev=++revision;detach();controller=new AbortController();const signal=controller.signal;play.disabled=true;replay.disabled=true;status.textContent='Loading the lifting film…';wanted=auto&&typeof matchMedia==='function'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;const ticket=playRevision;
  try{const response=await fetch('./assets/ramp-lever-corrected.mp4',{signal});if(!response.ok)throw Error('Unavailable');const blob=await response.blob();if(!current()||rev!==revision)return;
   source=URL.createObjectURL(new Blob([blob],{type:'video/mp4'}));video.muted=true;video.src=source;track=document.createElement('track');track.kind='captions';track.srclang='en';track.label='English';track.src='./assets/ramp-lever-corrected.vtt';video.append(track);track.track.mode='hidden';play.disabled=false;replay.disabled=false;status.textContent='';if(wanted&&ticket===playRevision&&active())requestPlay();
  }catch(e){if(current()&&rev===revision){wanted=false;status.textContent='';if(e?.name!=='AbortError')failure();}}
 };
 on(play,'click',()=>{if(!active()||play.disabled)return;if(video.paused)requestPlay();else pause();});on(replay,'click',()=>{if(!active()||replay.disabled)return;video.currentTime=0;requestPlay();});on(retry,'click',()=>{if(current())void load(false);});
 on(video,'play',()=>{if(!active()||(playTask&&(!wanted||playTask.serial!==playRevision||playTask.revision!==revision))){pause();return;}wanted=true;beforePlay();play.textContent='Pause';});on(video,'pause',()=>{wanted=false;playRevision++;if(current())play.textContent='Play';});on(video,'ended',()=>{wanted=false;updateCaption();});on(video,'timeupdate',updateCaption);on(video,'seeked',updateCaption);on(video,'error',failure);
 on(root.querySelector('[data-lift-film-transcript]'),'toggle',e=>{if(e.target.open&&current())pause();});on(document,'visibilitychange',()=>{if(document.hidden)pause();});on(window,'pagehide',pause);
 liftFilmCleanup=()=>{disposed=true;wanted=false;revision++;playRevision++;controller?.abort();off.forEach(fn=>fn());video.pause();detach();};void load(true);
}
